package enginetest

import (
	"github.com/dolthub/go-mysql-server/enginetest"
	"github.com/dolthub/go-mysql-server/enginetest/queries"
	"github.com/dolthub/go-mysql-server/sql"
	"testing"
)

var forkMergeCorrections = []queries.ScriptTest{
	{Name: "matching key change main", SetUpScript: []string{"CREATE TABLE t(a INT NOT NULL,b INT NOT NULL,v INT,PRIMARY KEY(a))", "INSERT INTO t VALUES(1,1,10),(2,2,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "CALL DOLT_COMMIT('-am','main key change')", "CALL DOLT_CHECKOUT('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "UPDATE t SET v=11 WHERE a=1", "CALL DOLT_COMMIT('-am','feature key change and edit')", "CALL DOLT_CHECKOUT('main')", "CALL DOLT_MERGE('feature')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT a,b,v FROM t ORDER BY a,b", Expected: []sql.Row{{1, 1, 11}, {2, 2, 20}}}, {Query: "SELECT COUNT(*) FROM dolt_conflicts", Expected: []sql.Row{{0}}}}},
	{Name: "matching key change feature", SetUpScript: []string{"CREATE TABLE t(a INT NOT NULL,b INT NOT NULL,v INT,PRIMARY KEY(a))", "INSERT INTO t VALUES(1,1,10),(2,2,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "CALL DOLT_COMMIT('-am','main key change')", "CALL DOLT_CHECKOUT('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "UPDATE t SET v=11 WHERE a=1", "CALL DOLT_COMMIT('-am','feature key change and edit')", "CALL DOLT_MERGE('main')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT a,b,v FROM t ORDER BY a,b", Expected: []sql.Row{{1, 1, 11}, {2, 2, 20}}}, {Query: "SELECT COUNT(*) FROM dolt_conflicts", Expected: []sql.Row{{0}}}}},
	{Name: "matching key change main squash", SetUpScript: []string{"CREATE TABLE t(a INT NOT NULL,b INT NOT NULL,v INT,PRIMARY KEY(a))", "INSERT INTO t VALUES(1,1,10),(2,2,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "CALL DOLT_COMMIT('-am','main key change')", "CALL DOLT_CHECKOUT('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "UPDATE t SET v=11 WHERE a=1", "CALL DOLT_COMMIT('-am','feature key change and edit')", "CALL DOLT_CHECKOUT('main')", "CALL DOLT_MERGE('feature','--squash')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT a,b,v FROM t ORDER BY a,b", Expected: []sql.Row{{1, 1, 11}, {2, 2, 20}}}, {Query: "SELECT COUNT(*) FROM dolt_conflicts", Expected: []sql.Row{{0}}}}},
	{Name: "string primary key and retained secondary indexes", SetUpScript: []string{"CREATE TABLE t(a INT PRIMARY KEY,b VARCHAR(80) NOT NULL,v INT,UNIQUE KEY uq(b),KEY iv(v))", "INSERT INTO t VALUES(1,'one',10),(2,'two',20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(b)", "UPDATE t SET v=12 WHERE a=1", "CALL DOLT_COMMIT('-am','main key and row')", "CALL DOLT_CHECKOUT('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(b)", "UPDATE t SET v=21 WHERE a=2", "CALL DOLT_COMMIT('-am','feature key and other row')", "CALL DOLT_CHECKOUT('main')", "CALL DOLT_MERGE('feature')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT a,b,v FROM t ORDER BY a", Expected: []sql.Row{{1, "one", 12}, {2, "two", 21}}}, {Query: "SELECT a,v FROM t FORCE INDEX(uq) WHERE b='two'", Expected: []sql.Row{{2, 21}}}, {Query: "SELECT a FROM t FORCE INDEX(iv) WHERE v=12", Expected: []sql.Row{{1}}}}},
	{Name: "ancestor collision refuses without changing roots", SetUpScript: []string{"CREATE TABLE t(a INT PRIMARY KEY,b INT,v INT)", "INSERT INTO t VALUES(1,7,10),(2,7,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "DELETE FROM t WHERE a=2", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(b)", "CALL DOLT_COMMIT('-am','main key change')", "CALL DOLT_CHECKOUT('feature')", "DELETE FROM t WHERE a=2", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(b)", "UPDATE t SET v=v+1", "CALL DOLT_COMMIT('-am','feature key change and edit')", "CALL DOLT_CHECKOUT('main')", "SET @before_head=HASHOF('HEAD')", "SET @before_work=DOLT_HASHOF_DB('WORKING')"}, Assertions: []queries.ScriptTestAssertion{{Query: "CALL DOLT_MERGE('feature')", ExpectedErrStr: "cannot re-key ancestor of t: rows collide under the new primary key"}, {Query: "SELECT HASHOF('HEAD')=@before_head,DOLT_HASHOF_DB('WORKING')=@before_work", Expected: []sql.Row{{true, true}}}}},
	{Name: "ancestor NULL refuses without changing roots", SetUpScript: []string{"CREATE TABLE t(a INT PRIMARY KEY,b INT,v INT)", "INSERT INTO t VALUES(1,NULL,10),(2,7,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "DELETE FROM t WHERE b IS NULL", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(b)", "CALL DOLT_COMMIT('-am','main key change')", "CALL DOLT_CHECKOUT('feature')", "DELETE FROM t WHERE b IS NULL", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(b)", "UPDATE t SET v=v+1", "CALL DOLT_COMMIT('-am','feature key change and edit')", "CALL DOLT_CHECKOUT('main')", "SET @before_head=HASHOF('HEAD')", "SET @before_work=DOLT_HASHOF_DB('WORKING')"}, Assertions: []queries.ScriptTestAssertion{{Query: "CALL DOLT_MERGE('feature')", ExpectedErrStr: "cannot re-key ancestor of t: NULL in the new primary key"}, {Query: "SELECT HASHOF('HEAD')=@before_head,DOLT_HASHOF_DB('WORKING')=@before_work", Expected: []sql.Row{{true, true}}}}},
	{Name: "rekeyed conflict retains readable ancestor values", SetUpScript: []string{"CREATE TABLE t(a INT NOT NULL,b INT NOT NULL,v INT,PRIMARY KEY(a))", "INSERT INTO t VALUES(1,1,10),(2,2,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "UPDATE t SET v=12 WHERE a=1", "CALL DOLT_COMMIT('-am','main edit')", "CALL DOLT_CHECKOUT('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "UPDATE t SET v=11 WHERE a=1", "CALL DOLT_COMMIT('-am','feature edit')", "CALL DOLT_CHECKOUT('main')", "SET autocommit=0", "SET @@dolt_allow_commit_conflicts=1", "CALL DOLT_MERGE('feature')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT base_a,base_b,base_v,our_v,their_v FROM dolt_conflicts_t", Expected: []sql.Row{{1, 1, 10, 12, 11}}}}},
	{Name: "virtual base all diff functions and unchanged branch history", SetUpScript: []string{"CREATE TABLE t (id INT PRIMARY KEY, v VARCHAR(20))", "CALL DOLT_COMMIT('-Am', 'c1: create table')", "CALL DOLT_BRANCH('schema')", "-- data-free branch for schema changes\nINSERT INTO t VALUES (1, 'seed'), (2, 'seed')", "CALL DOLT_COMMIT('-am', 'c2: seed rows on main')", "CALL DOLT_BRANCH('feature')", "-- feature forks from c2\nUPDATE t SET v = 'edited on main' WHERE id = 1", "DELETE FROM t WHERE id = 2", "CALL DOLT_COMMIT('-am', 'c3: main edits row 1 and deletes row 2')", "CALL DOLT_CHECKOUT('feature')", "INSERT INTO t VALUES (50, 'feature')", "CALL DOLT_COMMIT('-am', 'f1: feature adds row 50')", "CALL DOLT_CHECKOUT('schema')", "ALTER TABLE t ADD COLUMN n INT NULL", "CALL DOLT_COMMIT('-am', 's1: add column n')", "ALTER TABLE t ADD COLUMN m INT NULL", "CALL DOLT_COMMIT('-am', 's2: add column m')", "CALL DOLT_CHECKOUT('main')", "CALL DOLT_MERGE('schema', '-m', 'merge schema into main')", "CALL DOLT_CHECKOUT('feature')", "CALL DOLT_MERGE('schema', '-m', 'merge schema into feature')", "CALL DOLT_CHECKOUT('main')", "SET @before_head=HASHOF('HEAD')", "SET @before_work=DOLT_HASHOF_DB('WORKING')", "SET @before_log=(SELECT COUNT(*) FROM DOLT_LOG('--all'))"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT COUNT(*) FROM DOLT_MERGE_BASES('main','feature')", Expected: []sql.Row{{2}}}, {Query: "SELECT diff_type,to_id,to_v FROM DOLT_DIFF('main...feature','t')", Expected: []sql.Row{{"added", 50, "feature"}}}, {Query: "SELECT rows_added,rows_deleted,rows_modified FROM DOLT_DIFF_STAT('main...feature','t')", Expected: []sql.Row{{1, 0, 0}}}, {Query: "SELECT data_change,schema_change FROM DOLT_DIFF_SUMMARY('main...feature')", Expected: []sql.Row{{true, false}}}, {Query: "SELECT HASHOF('HEAD')=@before_head,DOLT_HASHOF_DB('WORKING')=@before_work,(SELECT COUNT(*) FROM DOLT_LOG('--all'))=@before_log", Expected: []sql.Row{{true, true, true}}}, {Query: "SELECT (SELECT MIN(from_commit) FROM DOLT_DIFF('main...feature','t'))=(SELECT MIN(from_commit) FROM DOLT_DIFF('main...feature','t'))", Expected: []sql.Row{{true}}}}},
	{Name: "virtual base preserves main edit and deletion", SetUpScript: []string{"CREATE TABLE t (id INT PRIMARY KEY, v VARCHAR(20))", "CALL DOLT_COMMIT('-Am', 'c1: create table')", "CALL DOLT_BRANCH('schema')", "-- data-free branch for schema changes\nINSERT INTO t VALUES (1, 'seed'), (2, 'seed')", "CALL DOLT_COMMIT('-am', 'c2: seed rows on main')", "CALL DOLT_BRANCH('feature')", "-- feature forks from c2\nUPDATE t SET v = 'edited on main' WHERE id = 1", "DELETE FROM t WHERE id = 2", "CALL DOLT_COMMIT('-am', 'c3: main edits row 1 and deletes row 2')", "CALL DOLT_CHECKOUT('feature')", "INSERT INTO t VALUES (50, 'feature')", "CALL DOLT_COMMIT('-am', 'f1: feature adds row 50')", "CALL DOLT_CHECKOUT('schema')", "ALTER TABLE t ADD COLUMN n INT NULL", "CALL DOLT_COMMIT('-am', 's1: add column n')", "ALTER TABLE t ADD COLUMN m INT NULL", "CALL DOLT_COMMIT('-am', 's2: add column m')", "CALL DOLT_CHECKOUT('main')", "CALL DOLT_MERGE('schema', '-m', 'merge schema into main')", "CALL DOLT_CHECKOUT('feature')", "CALL DOLT_MERGE('schema', '-m', 'merge schema into feature')", "CALL DOLT_CHECKOUT('main')", "SET @before_head=HASHOF('HEAD')", "SET @before_work=DOLT_HASHOF_DB('WORKING')", "SET @before_log=(SELECT COUNT(*) FROM DOLT_LOG('--all'))", "CALL DOLT_CHECKOUT('feature')", "CALL DOLT_MERGE('main','-m','apply main')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT id,v FROM t ORDER BY id", Expected: []sql.Row{{1, "edited on main"}, {50, "feature"}}}, {Query: "SELECT COUNT(*) FROM dolt_conflicts", Expected: []sql.Row{{0}}}}},
	{Name: "three best common ancestors are retained before merging", SetUpScript: []string{"CREATE TABLE t(id INT PRIMARY KEY,v INT)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('b0')", "CALL DOLT_BRANCH('c0')", "INSERT INTO t VALUES(1,10)", "CALL DOLT_COMMIT('-am','a')", "CALL DOLT_BRANCH('a0')", "CALL DOLT_CHECKOUT('b0')", "INSERT INTO t VALUES(2,20)", "CALL DOLT_COMMIT('-am','b')", "CALL DOLT_CHECKOUT('c0')", "INSERT INTO t VALUES(3,30)", "CALL DOLT_COMMIT('-am','c')", "CALL DOLT_BRANCH('x','a0')", "CALL DOLT_CHECKOUT('x')", "CALL DOLT_MERGE('b0')", "CALL DOLT_MERGE('c0')", "UPDATE t SET v=11 WHERE id=1", "CALL DOLT_COMMIT('-am','x edit')", "CALL DOLT_BRANCH('y','b0')", "CALL DOLT_CHECKOUT('y')", "CALL DOLT_MERGE('c0')", "CALL DOLT_MERGE('a0')", "UPDATE t SET v=21 WHERE id=2", "CALL DOLT_COMMIT('-am','y edit')", "CALL DOLT_CHECKOUT('x')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT COUNT(*) FROM DOLT_MERGE_BASES('x','y')", Expected: []sql.Row{{3}}}, {Query: "SELECT diff_type,to_id,to_v FROM DOLT_DIFF('x...y','t')", Expected: []sql.Row{{"modified", 2, 21}}}}},
	{Name: "three best common ancestors combine cleanly", SetUpScript: []string{"CREATE TABLE t(id INT PRIMARY KEY,v INT)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('b0')", "CALL DOLT_BRANCH('c0')", "INSERT INTO t VALUES(1,10)", "CALL DOLT_COMMIT('-am','a')", "CALL DOLT_BRANCH('a0')", "CALL DOLT_CHECKOUT('b0')", "INSERT INTO t VALUES(2,20)", "CALL DOLT_COMMIT('-am','b')", "CALL DOLT_CHECKOUT('c0')", "INSERT INTO t VALUES(3,30)", "CALL DOLT_COMMIT('-am','c')", "CALL DOLT_BRANCH('x','a0')", "CALL DOLT_CHECKOUT('x')", "CALL DOLT_MERGE('b0')", "CALL DOLT_MERGE('c0')", "UPDATE t SET v=11 WHERE id=1", "CALL DOLT_COMMIT('-am','x edit')", "CALL DOLT_BRANCH('y','b0')", "CALL DOLT_CHECKOUT('y')", "CALL DOLT_MERGE('c0')", "CALL DOLT_MERGE('a0')", "UPDATE t SET v=21 WHERE id=2", "CALL DOLT_COMMIT('-am','y edit')", "CALL DOLT_CHECKOUT('x')", "CALL DOLT_MERGE('y')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT COUNT(*) FROM DOLT_MERGE_BASES('x','y')", Expected: []sql.Row{{1}}}, {Query: "SELECT * FROM t ORDER BY id", Expected: []sql.Row{{1, 11}, {2, 21}, {3, 30}}}}},
	{Name: "matching key change preserves foreign key references", SetUpScript: []string{"CREATE TABLE p(a INT PRIMARY KEY,b INT NOT NULL,v INT,UNIQUE KEY ua(a))", "CREATE TABLE c(id INT PRIMARY KEY,pid INT,CONSTRAINT fk FOREIGN KEY(pid) REFERENCES p(a))", "INSERT INTO p VALUES(1,1,10),(2,2,20)", "INSERT INTO c VALUES(10,1)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE p DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "UPDATE p SET v=11 WHERE a=1", "CALL DOLT_COMMIT('-am','main key and row')", "CALL DOLT_CHECKOUT('feature')", "ALTER TABLE p DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "UPDATE p SET v=21 WHERE a=2", "CALL DOLT_COMMIT('-am','feature key and row')", "CALL DOLT_CHECKOUT('main')", "CALL DOLT_MERGE('feature')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT c.id,p.a,p.v FROM c JOIN p ON c.pid=p.a", Expected: []sql.Row{{10, 1, 11}}}, {Query: "SELECT COUNT(*) FROM dolt_constraint_violations", Expected: []sql.Row{{0}}}}},
	{Name: "conflicting best common ancestors refuse without state changes", SetUpScript: []string{"CREATE TABLE t(id INT PRIMARY KEY,v INT)", "INSERT INTO t VALUES(1,0)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('b')", "UPDATE t SET v=1", "CALL DOLT_COMMIT('-am','a')", "CALL DOLT_BRANCH('a0')", "CALL DOLT_CHECKOUT('b')", "UPDATE t SET v=2", "CALL DOLT_COMMIT('-am','b')", "CALL DOLT_BRANCH('b0')", "SET autocommit=0", "SET @@dolt_allow_commit_conflicts=1", "CALL DOLT_CHECKOUT('main')", "CALL DOLT_MERGE('b0')", "CALL DOLT_CONFLICTS_RESOLVE('--ours','t')", "CALL DOLT_COMMIT('-am','a resolves')", "CALL DOLT_CHECKOUT('b')", "CALL DOLT_MERGE('a0')", "CALL DOLT_CONFLICTS_RESOLVE('--ours','t')", "CALL DOLT_COMMIT('-am','b resolves')", "CALL DOLT_CHECKOUT('main')", "SET @before_head=HASHOF('HEAD')", "SET @before_work=DOLT_HASHOF_DB('WORKING')"}, Assertions: []queries.ScriptTestAssertion{{Query: "SELECT COUNT(*) FROM DOLT_MERGE_BASES('main','b')", Expected: []sql.Row{{2}}}, {Query: "SELECT * FROM DOLT_DIFF('main...b','t')", ExpectedErrStr: "best common ancestors conflict; virtual merge base requires explicit resolution"}, {Query: "CALL DOLT_MERGE('b')", ExpectedErrStr: "best common ancestors conflict; virtual merge base requires explicit resolution"}, {Query: "SELECT HASHOF('HEAD')=@before_head,DOLT_HASHOF_DB('WORKING')=@before_work", Expected: []sql.Row{{true, true}}}}},
	{Name: "one sided key change refuses without root changes", SetUpScript: []string{"CREATE TABLE t(a INT NOT NULL,b INT NOT NULL,v INT,PRIMARY KEY(a))", "INSERT INTO t VALUES(1,1,10),(2,2,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE t DROP PRIMARY KEY,ADD PRIMARY KEY(a,b)", "UPDATE t SET v=12 WHERE a=1", "CALL DOLT_COMMIT('-am','main schema and edit')", "CALL DOLT_CHECKOUT('feature')", "UPDATE t SET v=21 WHERE a=2", "CALL DOLT_COMMIT('-am','feature schema and edit')", "CALL DOLT_CHECKOUT('main')", "SET @before_head=HASHOF('HEAD')", "SET @before_work=DOLT_HASHOF_DB('WORKING')"}, Assertions: []queries.ScriptTestAssertion{{Query: "CALL DOLT_MERGE('feature')", ExpectedErrStr: "error: cannot merge because table t has different primary keys"}, {Query: "SELECT HASHOF('HEAD')=@before_head,DOLT_HASHOF_DB('WORKING')=@before_work", Expected: []sql.Row{{true, true}}}}},
	{Name: "new key column absent from ancestor refuses without root changes", SetUpScript: []string{"CREATE TABLE t(a INT NOT NULL,b INT NOT NULL,v INT,PRIMARY KEY(a))", "INSERT INTO t VALUES(1,1,10),(2,2,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE t ADD COLUMN c INT NOT NULL DEFAULT 0, DROP PRIMARY KEY, ADD PRIMARY KEY(a,c)", "UPDATE t SET v=12 WHERE a=1", "CALL DOLT_COMMIT('-am','main schema and edit')", "CALL DOLT_CHECKOUT('feature')", "ALTER TABLE t ADD COLUMN c INT NOT NULL DEFAULT 0, DROP PRIMARY KEY, ADD PRIMARY KEY(a,c)", "UPDATE t SET v=21 WHERE a=2", "CALL DOLT_COMMIT('-am','feature schema and edit')", "CALL DOLT_CHECKOUT('main')", "SET @before_head=HASHOF('HEAD')", "SET @before_work=DOLT_HASHOF_DB('WORKING')"}, Assertions: []queries.ScriptTestAssertion{{Query: "CALL DOLT_MERGE('feature')", ExpectedErrStr: "error: cannot merge because table t has different primary keys in its common ancestor"}, {Query: "SELECT HASHOF('HEAD')=@before_head,DOLT_HASHOF_DB('WORKING')=@before_work", Expected: []sql.Row{{true, true}}}}},
	{Name: "new key type differs from ancestor refuses without root changes", SetUpScript: []string{"CREATE TABLE t(a INT NOT NULL,b INT NOT NULL,v INT,PRIMARY KEY(a))", "INSERT INTO t VALUES(1,1,10),(2,2,20)", "CALL DOLT_COMMIT('-Am','base')", "CALL DOLT_BRANCH('feature')", "ALTER TABLE t MODIFY b BIGINT NOT NULL, DROP PRIMARY KEY, ADD PRIMARY KEY(a,b)", "UPDATE t SET v=12 WHERE a=1", "CALL DOLT_COMMIT('-am','main schema and edit')", "CALL DOLT_CHECKOUT('feature')", "ALTER TABLE t MODIFY b BIGINT NOT NULL, DROP PRIMARY KEY, ADD PRIMARY KEY(a,b)", "UPDATE t SET v=21 WHERE a=2", "CALL DOLT_COMMIT('-am','feature schema and edit')", "CALL DOLT_CHECKOUT('main')", "SET @before_head=HASHOF('HEAD')", "SET @before_work=DOLT_HASHOF_DB('WORKING')"}, Assertions: []queries.ScriptTestAssertion{{Query: "CALL DOLT_MERGE('feature')", ExpectedErrStr: "error: cannot merge because table t has different primary keys in its common ancestor"}, {Query: "SELECT HASHOF('HEAD')=@before_head,DOLT_HASHOF_DB('WORKING')=@before_work", Expected: []sql.Row{{true, true}}}}},
}

func TestForkMergeCorrections(t *testing.T) {
	for _, script := range forkMergeCorrections {
		t.Run(script.Name, func(t *testing.T) { h := newDoltHarness(t); defer h.Close(); enginetest.TestScript(t, h, script) })
	}
}
func TestForkMergeCorrectionsPrepared(t *testing.T) {
	for _, script := range forkMergeCorrections {
		t.Run(script.Name, func(t *testing.T) {
			h := newDoltHarness(t)
			defer h.Close()
			enginetest.TestScriptPrepared(t, h, script)
		})
	}
}
